{
  "kind": "method",
  "name": "sendVideoNote",
  "url": "https://core.telegram.org/bots/api#sendvideonote",
  "description": "Use this method to send a rounded square MPEG4 video of up to 1 minute long. On success, the sent Message is returned.",
  "returns": "On success, the sent Message is returned.",
  "params": {
    "business_connection_id": {
      "type": "String",
      "required": false,
      "description": "Unique identifier of the business connection on behalf of which the message will be sent"
    },
    "chat_id": {
      "type": "Integer or String",
      "required": false,
      "description": "Unique identifier for the target chat or username of the target bot, supergroup, or channel in the format `@username`; required unless the message is sent as an ephemeral reply to a callback query",
      "required_unless": "required unless the message is sent as an ephemeral reply to a callback query"
    },
    "message_thread_id": {
      "type": "Integer",
      "required": false,
      "description": "Unique identifier for the target message thread (topic) of a forum; for forum supergroups and private chats of bots with forum topic mode enabled only"
    },
    "direct_messages_topic_id": {
      "type": "Integer",
      "required": false,
      "description": "Identifier of the direct messages topic to which the message will be sent; required if the message is sent to a direct messages chat"
    },
    "ephemeral_message_parameters": {
      "type": "EphemeralMessageParameters",
      "required": false,
      "description": "A JSON-serialized object containing the parameters of the ephemeral message to send"
    },
    "video_note": {
      "type": "InputFile or String",
      "required": true,
      "description": "Video note to send. Pass a file_id as String to send a video note that exists on the Telegram servers (recommended) or upload a new video using multipart/form-data. More information on Sending Files ». Sending video notes by a URL is currently unsupported."
    },
    "duration": {
      "type": "Integer",
      "required": false,
      "description": "Duration of sent video in seconds"
    },
    "length": {
      "type": "Integer",
      "required": false,
      "description": "Video width and height, i.e. diameter of the video message"
    },
    "thumbnail": {
      "type": "InputFile or String",
      "required": false,
      "description": "Thumbnail of the file sent; can be ignored if thumbnail generation for the file is supported server-side. The thumbnail should be in JPEG format and less than 200 kB in size. A thumbnail's width and height should not exceed 320. Ignored if the file is not uploaded using multipart/form-data. Thumbnails can't be reused and can be only uploaded as a new file, so you can pass “attach://<file_attach_name>” if the thumbnail was uploaded using multipart/form-data under <file_attach_name>. More information on Sending Files »"
    },
    "disable_notification": {
      "type": "Boolean",
      "required": false,
      "description": "Sends the message silently. Users will receive a notification with no sound."
    },
    "protect_content": {
      "type": "Boolean",
      "required": false,
      "description": "Protects the contents of the sent message from forwarding and saving"
    },
    "allow_paid_broadcast": {
      "type": "Boolean",
      "required": false,
      "description": "Pass True to allow up to 1000 messages per second, ignoring broadcasting limits for a fee of 0.1 Telegram Stars per message. The relevant Stars will be withdrawn from the bot's balance."
    },
    "message_effect_id": {
      "type": "String",
      "required": false,
      "description": "Unique identifier of the message effect to be added to the message; for private chats only"
    },
    "suggested_post_parameters": {
      "type": "SuggestedPostParameters",
      "required": false,
      "description": "A JSON-serialized object containing the parameters of the suggested post to send; for direct messages chats only. If the message is sent as a reply to another suggested post, then that suggested post is automatically declined."
    },
    "reply_parameters": {
      "type": "ReplyParameters",
      "required": false,
      "description": "Description of the message to reply to"
    },
    "reply_markup": {
      "type": "InlineKeyboardMarkup or ReplyKeyboardMarkup or ReplyKeyboardRemove or ForceReply",
      "required": false,
      "description": "Additional interface options. A JSON-serialized object for an inline keyboard, custom reply keyboard, instructions to remove a reply keyboard or to force a reply from the user."
    }
  },
  "changes": [
    {
      "version": "10.4",
      "date": "November 9, 2026",
      "url": "https://core.telegram.org/bots/api-changelog#november-9-2026",
      "text": "Allowed bots to send ephemeral replies to callback queries in any chat except channel direct messages chats by specifying callback_query_id without receiver_user_id in the parameter ephemeral_message_parameters of the methods sendMessage, sendRichMessage, sendAnimation, sendAudio, sendContact, sendDocument, sendLivePhoto, sendLocation, sendPhoto, sendSticker, sendVenue, sendVideo, sendVideoNote and sendVoice."
    },
    {
      "version": "10.3",
      "date": "August 24, 2026",
      "url": "https://core.telegram.org/bots/api-changelog#august-24-2026",
      "text": "Added the class EphemeralMessageParameters and replaced the parameters receiver_user_id and callback_query_id in the methods sendMessage, sendAnimation, sendAudio, sendDocument, sendLivePhoto, sendPhoto, sendSticker, sendVideo, sendVideoNote, sendVoice, sendContact, sendLocation and sendVenue with the parameter ephemeral_message_parameters."
    },
    {
      "version": "10.2",
      "date": "July 14, 2026",
      "url": "https://core.telegram.org/bots/api-changelog#july-14-2026",
      "text": "Added the parameters receiver_user_id and callback_query_id to the methods sendMessage, sendAnimation, sendAudio, sendDocument, sendLivePhoto, sendPhoto, sendSticker, sendVideo, sendVideoNote, sendVoice, sendContact, sendLocation, sendVenue."
    },
    {
      "version": "9.3",
      "date": "December 31, 2025",
      "url": "https://core.telegram.org/bots/api-changelog#december-31-2025",
      "text": "Supported the parameter message_thread_id in private chats with topics in the methods sendMessage, sendPhoto, sendVideo, sendAnimation, sendAudio, sendDocument, sendPaidMedia, sendSticker, sendVideoNote, sendVoice, sendLocation, sendVenue, sendContact, sendPoll, sendDice, sendInvoice, sendGame, sendMediaGroup, copyMessage, copyMessages, forwardMessage, and forwardMessages, allowing bots to send a message to a specific topic."
    },
    {
      "version": "9.2",
      "date": "August 15, 2025",
      "url": "https://core.telegram.org/bots/api-changelog#august-15-2025",
      "text": "Added the parameter direct_messages_topic_id to the methods sendMessage, sendPhoto, sendVideo, sendAnimation, sendAudio, sendDocument, sendPaidMedia, sendSticker, sendVideoNote, sendVoice, sendLocation, sendVenue, sendContact, sendDice, sendInvoice, sendMediaGroup, copyMessage, copyMessages, forwardMessage and forwardMessages. This parameter can be used to send a message to a direct messages chat topic."
    },
    {
      "version": "9.2",
      "date": "August 15, 2025",
      "url": "https://core.telegram.org/bots/api-changelog#august-15-2025",
      "text": "Added the class SuggestedPostParameters and the parameter suggested_post_parameters to the methods sendMessage, sendPhoto, sendVideo, sendAnimation, sendAudio, sendDocument, sendPaidMedia, sendSticker, sendVideoNote, sendVoice, sendLocation, sendVenue, sendContact, sendDice, sendInvoice, copyMessage, forwardMessage. This parameter can be used to send a suggested post to a direct messages chat topic."
    }
  ],
